from base64 import b64decode

from fastapi import APIRouter
from fastapi.responses import Response

router = APIRouter()

# Embedded favicon assets so Vercel doesn't depend on filesystem packaging.
FAVICON_ICO_B64 = ""
FAVICON_PNG_B64 = ""


@router.get('/favicon.ico', include_in_schema=False)
def favicon_ico():
    return Response(content=b64decode(FAVICON_ICO_B64), media_type='image/x-icon')


@router.get('/favicon.png', include_in_schema=False)
def favicon_png():
    return Response(content=b64decode(FAVICON_PNG_B64), media_type='image/png')
